'use client'

import { useEffect, useState } from 'react'
import { Canvas, FabricImage, Textbox } from 'fabric'
import { renderBrowserSide } from '@/lib/editor/browser-preview'

export default function CanvasFixVerificationPage() {
  const [result, setResult] = useState('RUNNING')
  useEffect(() => {
    let disposed = false
    const verify = async () => {
      const canvas = new Canvas(document.createElement('canvas'), { width: 400, height: 200, backgroundColor: '#ffffff' })
      try {
        const image = await FabricImage.fromURL('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=')
        image.set({ left: 55, top: 40, angle: 27, scaleX: 70, scaleY: 90, flipX: true })
        canvas.add(image, new Textbox('Canvas preview text', { left: 175, top: 85, width: 180, fontSize: 24, fill: '#ed1b68', angle: -8 }))
        const rendered = await renderBrowserSide(canvas.toJSON() as Record<string, unknown>, { widthMm: 1000, heightMm: 500, bleedMm: 3, safeMarginMm: 10, logicalCanvasWidth: 400, logicalCanvasHeight: 200 })
        const valid = rendered.preview.blob.size > 0 && rendered.production.blob.size > 0
          && rendered.preview.pixelWidth === 800 && rendered.preview.pixelHeight === 400
          && rendered.production.pixelWidth === 2000 && rendered.production.pixelHeight === 1000
        if (!disposed) setResult(valid ? 'PASS:image,text,rotation,mirror,scale,dimensions' : 'FAIL:render-output')
      } finally {
        canvas.dispose()
      }
    }
    void verify().catch((error) => { if (!disposed) setResult(`FAIL:${error instanceof Error ? error.message : 'unknown'}`) })
    return () => { disposed = true }
  }, [])
  return <output id="canvasfix01-result">{result}</output>
}
